-- Biology Ch1 (The Cell) — Batch 1 of 4: Eukaryotic membrane-bound organelles (AAMC 2A "Cell and Tissue Structure (BIO)")
-- 25 questions, all confidence >=4 (each fact + each distractor's wrongness cited to OpenStax Biology 2e, Ch.4 Cell Structure).
-- Difficulty 7 easy / 10 medium / 8 hard (every hard passes the two-axis Hard-Tier gate, >=2 of 4 structural conditions);
-- answer key A/B/C/D = 6/7/6/6; skills 8x1 / 14x2 / 3x4; 3 data-driven (inline tables) + 1 Roman-numeral; all distractors single-variable.
-- section bio_biochem, discipline biology, foundation 2A. Figure-free (inline LaTeX tables; no figure_svg needed for this batch).
-- Re-runnable: subtopic-scoped DELETE (preserves other Ch1 batches). Run in the Supabase SQL editor.
BEGIN;
DELETE FROM questions WHERE topic = 'The Cell' AND subtopic IN ('Endomembrane System & Organelle Identification', 'Endoplasmic Reticulum', 'Golgi Apparatus', 'Lysosomes', 'Mitochondria', 'Nucleus', 'Peroxisomes');

-- Q1 [Endomembrane System & Organelle Identification · hard · Skill 2 · ans A] (g3)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Cell', 'Endomembrane System & Organelle Identification',
    $qt3$A pancreatic acinar cell synthesizes digestive enzymes that are released into the duct lumen as glycoproteins. A researcher attaches a fluorescent tag to one such enzyme the instant its polypeptide first acquires a carbohydrate group, then tracks the tagged molecule until it leaves the cell. Where does the enzyme MOST likely first acquire that carbohydrate, and what is its final step before release?$qt3$,
    $op3$[{"label":"A","text":"It first acquires the carbohydrate in the rough endoplasmic reticulum lumen, and is released when a secretory vesicle from the Golgi fuses with the plasma membrane."},{"label":"B","text":"It first acquires the carbohydrate in the Golgi apparatus, and is released when a secretory vesicle from the Golgi fuses with the plasma membrane."},{"label":"C","text":"It first acquires the carbohydrate in the rough endoplasmic reticulum lumen, and is released when a lysosome fuses with the plasma membrane."},{"label":"D","text":"It first acquires the carbohydrate on a cytoplasmic ribosome, and is released when a secretory vesicle from the Golgi fuses with the plasma membrane."}]$op3$::jsonb,
    'A',
    $ex3$This is a Biology question that falls under the content category 'Cell and Tissue Structure (BIO)'. The answer is A because carbohydrate attachment to a secreted glycoprotein first occurs in the rough endoplasmic reticulum (RER), and the molecule's final step is exocytosis when a Golgi-derived secretory vesicle fuses with the plasma membrane. As a ribosome on the RER translates the enzyme, the polypeptide enters the RER lumen, where it is modified—including the initial attachment of a carbohydrate (OpenStax 4.4, Figure 4.18, lines 5664-5667: \"a (green) integral membrane protein is modified by attachment of a (purple) carbohydrate in the ER\"; lines 5699-5702: \"Ribosomes transfer their newly synthesized proteins into the RER's lumen where they undergo structural modifications... The proteins can also secrete from the cell\"). The protein then travels by transport vesicle to the Golgi cis face, where \"the addition of more carbohydrates further modifies it\" (lines 5666-5667) and it is sorted and tagged. Finally it is \"packaged into secretory vesicles that bud from the Golgi's trans face\" which \"fuse with the plasma membrane and release their contents outside the cell\" (lines 5771-5773). (Choice A) Correct: the carbohydrate is added in the ER lumen first and the Golgi later adds more, so the FIRST attachment site is the RER; exocytosis of a Golgi-derived secretory vesicle is indeed the terminal step for a secreted enzyme. (Choice B) Partial-truth trap: the Golgi genuinely glycosylates proteins—\"the most frequent modification is adding short sugar molecule chains\" (lines 5766-5767)—but it adds MORE carbohydrate to a chain that began in the ER (\"the addition of more carbohydrates further modifies it,\" lines 5666-5667); because the stem asks where the carbohydrate is FIRST acquired, the Golgi is the site of subsequent, not initial, glycosylation. (Choice C) Reversed/incorrect destination: lysosomes are the cell's \"garbage disposal\" whose acidic hydrolytic enzymes break down macromolecules and worn-out organelles (lines 5547-5557); they degrade intracellular material rather than fusing with the plasma membrane to release a functional secreted enzyme, so this misroutes the exocytic step. (Choice D) Process-step confusion: free cytoplasmic ribosomes synthesize the polypeptide, but glycosylation does not occur on the ribosome itself—the protein must first be transferred into the RER lumen, where modifications such as carbohydrate attachment take place (lines 5699-5702), so the carbohydrate cannot be acquired on a cytoplasmic ribosome. This is a Scientific Reasoning and Problem Solving question because you must integrate the sequence of endomembrane events and apply it to predict where carbohydrate is first added and what the terminal secretory step is.$ex3$,
    'hard', '2A', $cc3$Cell and Tissue Structure (BIO)$cc3$, 'biology', 2, 150
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'partial_truth', $a3B$Golgi-glycosylation-true-but-not-first: correct that the Golgi adds sugars, wrong that it is the initial glycosylation site$a3B$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a3C$lysosome-as-secretory-vesicle: confusing the degradative organelle with the exocytic secretory vesicle$a3C$ FROM q
UNION ALL SELECT id, 'D', 'process_step_confusion', $a3D$ribosome-as-modification-site: attributing co-translational lumenal modification to the ribosome itself$a3D$ FROM q;

-- Q2 [Endomembrane System & Organelle Identification · hard · Skill 4 · ans A] (g6)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Cell', 'Endomembrane System & Organelle Identification',
    $qt6$A researcher disrupts liver cells and separates the homogenate by differential centrifugation into three fractions, then assays each for three marker enzymes. Acid phosphatase marks lysosomes, cytochrome c oxidase marks mitochondria, and catalase marks peroxisomes. Relative activity (units per mg protein) is shown below. \(\begin{array}{lccc} \text{Marker enzyme} & \text{Fraction I} & \text{Fraction II} & \text{Fraction III} \\ \text{Acid phosphatase} & 8 & 5 & 71 \\ \text{Cytochrome c oxidase} & 64 & 9 & 6 \\ \text{Catalase} & 7 & 73 & 10 \end{array}\) The organelle that most likely predominates in Fraction II is the:$qt6$,
    $op6$[{"label":"A","text":"peroxisome, because its catalase detoxifies \\(\\text{H}_2\\text{O}_2\\) generated during oxidation reactions"},{"label":"B","text":"mitochondrion, because its cytochrome c oxidase consumes \\(\\text{O}_2\\) during oxidation reactions"},{"label":"C","text":"lysosome, because its acid hydrolases degrade macromolecules at low pH"},{"label":"D","text":"chloroplast, because its catalase supports the oxidative reactions of metabolism"}]$op6$::jsonb,
    'A',
    $ex6$This is a Biology question that falls under the content category 'Cell and Tissue Structure (BIO)'. The answer is A because catalase is the peroxisomal marker enzyme, and Fraction II has by far the highest catalase activity, so it is enriched in peroxisomes. Each membrane-bound organelle carries signature enzymes, so the fraction in which a marker enzyme is most concentrated is the fraction enriched in that marker's organelle. The textbook states that peroxisomes "carry out oxidation reactions that break down fatty acids and amino acids" and that "many of these oxidation reactions release hydrogen peroxide, \(\text{H}_2\text{O}_2\) ... when these reactions are confined to peroxisomes, enzymes safely break down the \(\text{H}_2\text{O}_2\) into oxygen and water" (lines 5508-5511). Catalase is that confined enzyme, so its peak in Fraction II identifies the peroxisome; the data must be read as marker-to-organelle, not as the absolute size of any one number. (Choice A) is correct: catalase tracks the peroxisome, Fraction II's catalase activity (73) dwarfs its activity elsewhere, and the peroxisome is the organelle that detoxifies the \(\text{H}_2\text{O}_2\) byproduct of its own oxidation reactions, consistent with lines 5508-5511. (Choice B) is a partial-truth trap: cytochrome c oxidase does mark mitochondria and mitochondria do use \(\text{O}_2\) in oxidation reactions on the inner membrane (lines 5485-5488), but cytochrome c oxidase peaks in Fraction I (64), not Fraction II, so a reader who anchors on "oxidation reactions use oxygen, therefore mitochondria" reaches the wrong fraction. (Choice C) is wrong because acid phosphatase, the lysosomal acid-hydrolase marker active "at a much lower pH than the cytoplasm's" (lines 5548-5556), is highest in Fraction III (71), so lysosomes predominate there, not in Fraction II. (Choice D) is wrong because chloroplasts are plastids found only in plant cells, not in the liver tissue assayed, and they perform photosynthesis rather than serving as the home of catalase (lines 5594-5604); attributing the catalase signal to a chloroplast misassigns both the enzyme and the cell type. This is a Data-based and Statistical Reasoning question because you must compare marker-enzyme activities across centrifugation fractions and infer organelle identity from the enzyme that is most enriched, rather than reading a single value off the table.$ex6$,
    'hard', '2A', $cc6$Cell and Tissue Structure (BIO)$cc6$, 'biology', 4, 150
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'partial_truth', $a6B$correct-under-a-different-fraction: right marker-organelle pairing applied to the wrong fraction by anchoring on 'oxidation uses oxygen'$a6B$ FROM q
UNION ALL SELECT id, 'C', 'process_step_confusion', $a6C$valid marker-organelle pairing assigned to the wrong centrifugation fraction$a6C$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a6D$wrong-cell-type organelle (plant chloroplast) invoked for an animal liver sample with a misattributed enzyme$a6D$ FROM q;

-- Q3 [Endomembrane System & Organelle Identification · medium · Skill 1 · ans A] (g8)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Cell', 'Endomembrane System & Organelle Identification',
    $qt8$A researcher fractionates an animal cell and screens each membrane-bound compartment for a circular DNA molecule distinct from the nuclear genome, along with the machinery to self-replicate that DNA. Which of the listed structures is the screen MOST likely to flag as positive? (I) Mitochondria; (II) Nucleus; (III) Rough endoplasmic reticulum; (IV) Peroxisomes.$qt8$,
    $op8$[{"label":"A","text":"I only"},{"label":"B","text":"I and II"},{"label":"C","text":"I and IV"},{"label":"D","text":"II and III"}]$op8$::jsonb,
    'A',
    $ex8$This is a Biology question that falls under the content category 'Cell and Tissue Structure (BIO)'. The answer is A because, in an animal cell, the mitochondrion is the only listed compartment that carries its own DNA and the ribosomal machinery to replicate it independently of the nucleus. The textbook states that mitochondria "have their own ribosomes and DNA" (line 5485), and the endosymbiosis passage explains why: mitochondria descend from ingested aerobic bacteria, so they retain "DNA and ribosomes, just like" bacteria (lines 5611-5626). Among the four listed structures, only the mitochondrion fits the screen for a circular organellar genome plus self-replication machinery; chloroplasts share this trait but are absent from animal cells, leaving mitochondria as the sole positive. (Choice A) Correct. Only structure I (mitochondria) carries a genome separate from the nuclear DNA and the means to copy it; the endosymbiotic origin from a free-living bacterium accounts for both the circular DNA and the organelle's own ribosomes (lines 5485, 5611-5626). In an animal cell, chloroplasts (the other organelle with its own genome) are not present, so the set is correctly I only. (Choice B) The nucleus (II) houses the cell's chromatin and "the cell's DNA" (lines 5398, 5425-5428), but that is the nuclear genome itself organized into linear chromosomes, not a separate organellar circular genome; the screen seeks DNA distinct from the nuclear genome, so the nucleus is excluded by definition. (Choice C) Peroxisomes (IV) are "small, round organelles enclosed by single membranes" that carry out oxidation reactions (lines 5507-5508); they contain no DNA and do not appear in the endosymbiosis account, which names only mitochondria and chloroplasts as having their own genome (lines 5611, 5622-5627). (Choice D) The rough endoplasmic reticulum (III) is a component of the endomembrane system that modifies and transports proteins (lines 5648-5650); it is genome-free, and pairing it with the nucleus (II) doubles the error. This is a Knowledge of Scientific Concepts and Principles question because you must recall which eukaryotic organelles retain their own genome and self-replication machinery as a consequence of endosymbiotic origin.$ex8$,
    'medium', '2A', $cc8$Cell and Tissue Structure (BIO)$cc8$, 'biology', 1, 105
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'partial_truth', $a8B$Nucleus holds the cell's DNA, so a student treats the nuclear genome as a separate organellar genome rather than the cell's central linear-chromosome DNA$a8B$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a8C$Treats peroxisomes as semi-autonomous DNA-containing organelles like mitochondria because both are oval/round metabolic organelles$a8C$ FROM q
UNION ALL SELECT id, 'D', 'adjacent_fact', $a8D$Confuses endomembrane organelles (rough ER) and the nucleus with DNA-bearing self-replicating organelles$a8D$ FROM q;

-- Q4 [Endomembrane System & Organelle Identification · medium · Skill 4 · ans C] (g24)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Cell', 'Endomembrane System & Organelle Identification',
    $qt24$A fibroblast actively secreting collagen is given a brief pulse of radiolabeled amino acids, and the labeled procollagen recovered from three compartments is measured at three successive chase times: \( \begin{array}{cccc} \text{chase time} & \text{ER} & \text{Golgi} & \text{secretory vesicles} \\ 3\ \text{min} & 82\% & 14\% & 4\% \\ 20\ \text{min} & 18\% & 55\% & 27\% \\ 60\ \text{min} & 5\% & 21\% & 74\% \end{array} \) Based on the shifting distribution of label across the compartments, which trafficking route does the procollagen most likely follow?$qt24$,
    $op24$[{"label":"A","text":"It is made in secretory vesicles and moves backward through the Golgi to the ER."},{"label":"B","text":"It is synthesized first in the Golgi, then split between the ER and secretory vesicles."},{"label":"C","text":"It is synthesized in the ER and moves sequentially to the Golgi and then to secretory vesicles."},{"label":"D","text":"It enters the ER, Golgi, and secretory vesicles at the same time from a shared cytosolic pool."}]$op24$::jsonb,
    'C',
    $ex24$This is a Biology question that falls under the content category 'Cell and Tissue Structure (BIO)'. The answer is C because the label appears first and most heavily in the ER, then peaks in the Golgi at the intermediate time, and finally accumulates in secretory vesicles, tracing a one-way ER \( \to \) Golgi \( \to \) vesicle route. The text states that "Membrane and secretory proteins are synthesized in the rough endoplasmic reticulum (RER)" and that "Vesicles with the integral protein bud from the ER and fuse with the Golgi apparatus' cis face," after which the protein "exits as an integral membrane protein of the vesicle that buds from the Golgi's trans face." The data match this directional flow: at 3 min the label is \( 82\% \) in the ER (the site of synthesis), by 20 min it has shifted to the Golgi (\( 55\% \)), and by 60 min it is \( 74\% \) in secretory vesicles. Because the peak simply moves from one compartment to the next over time rather than appearing everywhere at once or in reverse, the procollagen must travel ER first, Golgi second, vesicles last. (Choice A) The reverse order is contradicted by the data, since the earliest time point shows label concentrated in the ER, not in secretory vesicles; the text places synthesis in the RER and budding from the Golgi's trans face last. (Choice B) Synthesis does not begin in the Golgi; the text specifies that secretory proteins "are synthesized in the rough endoplasmic reticulum," consistent with the label appearing in the ER first. (Choice C) Correct: the label moves ER \( \to \) Golgi \( \to \) secretory vesicles in sequence, matching the text's statement that vesicles bud from the ER, fuse with the Golgi cis face, and later bud from the trans face. (Choice D) Simultaneous entry from a cytosolic pool is ruled out because the compartments do not all label at once; the label shifts compartment by compartment, and the text describes vesicular transport between organelles rather than direct cytosolic loading of each one. This is a Data-based and Statistical Reasoning question because you must infer the direction of a transport pathway from how the percentage of label redistributes among compartments across successive time points.$ex24$,
    'medium', '2A', $cc24$Cell and Tissue Structure (BIO)$cc24$, 'biology', 4, 90
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'reversed_relationship', $a24A$Pathway direction reversed (vesicles to Golgi to ER)$a24A$ FROM q
UNION ALL SELECT id, 'B', 'process_step_confusion', $a24B$Synthesis misassigned to the Golgi instead of the ER$a24B$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a24D$Parallel loading from a shared cytosolic pool rather than sequential vesicular transport$a24D$ FROM q;

-- Q5 [Endomembrane System & Organelle Identification · hard · Skill 4 · ans D] (g25)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Cell', 'Endomembrane System & Organelle Identification',
    $qt25$A plant biologist isolates two double-membrane organelles—one a mitochondrion, one a chloroplast—from a single leaf cell; both organelles carry their own circular DNA and ribosomes. She then exposes both isolated organelles to a compound that completely and selectively inactivates cytochrome \(c\) oxidase. Assuming each organelle is supplied with its normal substrates and the chloroplast is illuminated, which outcome most directly follows?$qt25$,
    $op25$[{"label":"A","text":"The chloroplast halts ATP-coupled sugar synthesis while the mitochondrion is unaffected, because cytochrome \\(c\\) oxidase is the terminal enzyme of the chloroplast's light reactions"},{"label":"B","text":"Both organelles continue normally, because cytochrome \\(c\\) oxidase acts in the cytosol during glycolysis rather than inside either double-membrane organelle"},{"label":"C","text":"The mitochondrion's ATP output drops but continues at a reduced rate, because its matrix citric-acid-cycle enzymes are untouched and can still drive inner-membrane ATP synthesis on their own"},{"label":"D","text":"The mitochondrion's inner-membrane ATP synthesis stops while the illuminated chloroplast continues photosynthesis, because cytochrome \\(c\\) oxidase is a respiratory electron-transport component absent from the chloroplast"}]$op25$::jsonb,
    'D',
    $ex25$This is a Biology question that falls under the content category 'Cell and Tissue Structure (BIO)'. The answer is D because cytochrome \(c\) oxidase belongs to the mitochondrial inner-membrane electron-transport chain, so inactivating it halts mitochondrial ATP synthesis while leaving the chloroplast's photosynthetic light reactions—which do not use this enzyme—intact. Cytochrome \(c\) oxidase is "a component of the electron transport chain" (textbook line 9618), and in mitochondria "ATP synthesis takes place on the inner membrane" (line 5495), where the double-membrane, own-DNA "powerhouse" carries out cellular respiration to make ATP (lines 5474–5475, 5485). The chloroplast is the endosymbiotic near-twin—it too has "outer and inner membranes," "their own DNA and ribosomes," and "a single circular chromosome" (lines 5574, 5581, 5592)—but it has "an entirely different function," photosynthesis, which captures light energy in the thylakoid membranes (lines 5574–5575, 5590), not the respiratory electron-transport machinery that cytochrome \(c\) oxidase serves. The chain of reasoning is to locate cytochrome \(c\) oxidase in the respiratory ETC, recognize that only the mitochondrion runs that chain, and conclude the chloroplast's distinct photosynthetic pathway is spared. (Choice A) This reverses the organelle relationship: cytochrome \(c\) oxidase is a respiratory ETC enzyme of the mitochondrion (line 9618), not a chloroplast light-reaction enzyme, so the claim assigns the affected pathway to the wrong organelle and incorrectly spares the mitochondrion. (Choice B) Cytochrome \(c\) oxidase is not a cytosolic glycolytic enzyme; it is an inner-membrane component of the mitochondrial electron transport chain (lines 9618, 5495), so the perturbation does act inside the mitochondrion and the "both continue normally" prediction fails. (Choice C) This partial-truth trap is correct that the matrix citric-acid-cycle enzymes are not the direct target, but ATP synthesis depends on the inner-membrane electron-transport chain that cytochrome \(c\) oxidase completes (lines 9618, 5495); with the chain blocked, the proton gradient cannot be regenerated, so oxidative ATP synthesis stops rather than merely slowing. (Choice D) Correct: cytochrome \(c\) oxidase is a respiratory ETC component on the mitochondrial inner membrane where ATP synthesis occurs (lines 9618, 5495), and the chloroplast performs photosynthesis without this enzyme (lines 5574–5575), so only mitochondrial ATP synthesis stops. This is a Scientific Reasoning and Problem Solving question because you must predict the functional consequence of a targeted enzyme inactivation by tracing cytochrome \(c\) oxidase to the mitochondrial respiratory chain and distinguishing that pathway from the chloroplast's separate photosynthetic function.$ex25$,
    'hard', '2A', $cc25$Cell and Tissue Structure (BIO)$cc25$, 'biology', 4, 150
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'reversed_relationship', $a25A$Assigns the respiratory enzyme cytochrome c oxidase to the chloroplast's light reactions, swapping which endosymbiont-derived organelle is affected$a25A$ FROM q
UNION ALL SELECT id, 'B', 'process_step_confusion', $a25B$Misplaces cytochrome c oxidase into cytosolic glycolysis instead of the mitochondrial inner-membrane ETC$a25B$ FROM q
UNION ALL SELECT id, 'C', 'partial_truth', $a25C$Correctly notes the citric-acid-cycle matrix enzymes are untouched but wrongly concludes inner-membrane ATP synthesis merely slows rather than stops when the ETC is blocked$a25C$ FROM q;

-- Q6 [Endoplasmic Reticulum · medium · Skill 2 · ans B] (g7)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Cell', 'Endoplasmic Reticulum',
    $qt7$A pancreatic acinar cell is actively producing a digestive enzyme that will be packaged and exported from the cell. On which ribosome population is this enzyme most likely synthesized?$qt7$,
    $op7$[{"label":"A","text":"Ribosomes floating freely in the cytosol"},{"label":"B","text":"Ribosomes bound to the cytoplasmic surface of the rough endoplasmic reticulum"},{"label":"C","text":"Ribosomes embedded within the smooth endoplasmic reticulum"},{"label":"D","text":"Ribosomes located inside the mitochondrial matrix"}]$op7$::jsonb,
    'B',
    $ex7$This is a Biology question that falls under the content category 'Cell and Tissue Structure (BIO)'. The answer is B because proteins destined for secretion are synthesized by ribosomes attached to the rough endoplasmic reticulum, which threads the nascent chain into the RER lumen for processing and export. The textbook states that ribosomes \"may be attached to the plasma membrane's cytoplasmic side or the endoplasmic reticulum's cytoplasmic side\" (lines 5451-5452) and that \"Ribosomes transfer their newly synthesized proteins into the RER's lumen where they undergo structural modifications... The proteins can also secrete from the cell (such as protein hormones, enzymes)\" (lines 5699-5701). Because the RER is \"abundant in cells that secrete proteins\" (lines 5707-5708), a secreted digestive enzyme is most directly produced on RER-bound ribosomes. (Choice A) Free cytosolic ribosomes are a real population, but they reverse the relationship: they synthesize proteins that remain in the cytosol or are imported into the nucleus, not proteins routed for secretion, so a secreted enzyme would not begin on free ribosomes. (Choice B) This is correct: RER-bound ribosomes deposit the growing polypeptide directly into the RER lumen, the entry point of the secretory pathway, where the protein is folded and modified before being shipped out in transport vesicles. (Choice C) The smooth endoplasmic reticulum \"has few or no ribosomes on its cytoplasmic surface\" (line 5712) and specializes in lipid, carbohydrate, and steroid synthesis plus detoxification; lacking ribosomes, it cannot be the site of protein synthesis. (Choice D) Mitochondria do contain their own ribosomes (lines 5485), but those ribosomes make proteins for use inside the mitochondrion, not enzymes destined for secretion through the endomembrane system. This is a Scientific Reasoning and Problem Solving question because you must apply the rule linking ribosome location to a protein's destination in order to predict where a secreted enzyme is synthesized.$ex7$,
    'medium', '2A', $cc7$Cell and Tissue Structure (BIO)$cc7$, 'biology', 2, 100
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'reversed_relationship', $a7A$free ribosomes make cytosolic/nuclear proteins, not secreted ones$a7A$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a7C$treating smooth ER as a protein-synthesis site despite it lacking ribosomes$a7C$ FROM q
UNION ALL SELECT id, 'D', 'adjacent_fact', $a7D$mitochondrial ribosomes exist but serve the mitochondrion, not secretion$a7D$ FROM q;

-- Q7 [Endoplasmic Reticulum · easy · Skill 1 · ans C] (g16)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Cell', 'Endoplasmic Reticulum',
    $qt16$A liver hepatocyte takes up a lipophilic drug, and enzymes embedded in one of its membrane systems oxidize the drug to make it more water-soluble for excretion. Which structure is most directly responsible for this detoxification?$qt16$,
    $op16$[{"label":"A","text":"The rough endoplasmic reticulum, which folds and modifies newly synthesized proteins in its lumen"},{"label":"B","text":"Lysosomes, whose acid hydrolases break down macromolecules at a low internal pH"},{"label":"C","text":"The smooth endoplasmic reticulum, whose resident enzymes detoxify medications and poisons"},{"label":"D","text":"Free ribosomes, which translate messenger RNA into polypeptides in the cytoplasm"}]$op16$::jsonb,
    'C',
    $ex16$This is a Biology question that falls under the content category 'Cell and Tissue Structure (BIO)'. The answer is C because the smooth endoplasmic reticulum houses the membrane-bound enzymes (such as the cytochrome P450 system) that detoxify drugs and poisons. The OpenStax text states that "SER functions include synthesis of carbohydrates, lipids, and steroid hormones; detoxification of medications and poisons; and storing calcium ions" (lines 5712-5714). A lipophilic drug partitions into the SER membrane, where these resident oxidizing enzymes chemically modify it to a more water-soluble form that the cell can export; this is a metabolic detoxification step, not a protein-handling or bulk-degradation step. Hepatocytes are rich in SER precisely because the liver carries a heavy detoxification load. (Choice A) The rough ER is the wrong compartment: per the text, "Ribosomes transfer their newly synthesized proteins into the RER's lumen where they undergo structural modifications, such as folding or acquiring side chains" (lines 5699-5700), so the RER modifies proteins and makes phospholipids rather than oxidizing lipophilic drugs. (Choice B) Lysosomes use "enzymes... active at a much lower pH than the cytoplasm's" to hydrolyze "proteins, polysaccharides, lipids, nucleic acids, and even worn-out organelles" (lines 5550-5556); this is acid-driven bulk digestion of macromolecules, not the oxidative chemical conversion of a small lipophilic drug. (Choice C) Correct: the SER's enzymes carry out "detoxification of medications and poisons" (line 5714), and because it is continuous with the RER yet largely free of ribosomes it specializes in lipid-based and detoxification chemistry rather than protein output. (Choice D) Free ribosomes are protein-synthesis machinery: the text notes "Ribosomes are the cellular structures responsible for protein synthesis" and translate "the code provided by the sequence of the nitrogenous bases in the mRNA into a specific order of amino acids" (lines 5449-5456); they build polypeptides and do not metabolize drugs. This is a Knowledge of Scientific Concepts and Principles question because you must recall that the smooth endoplasmic reticulum, not the rough ER, lysosomes, or ribosomes, is the organelle that detoxifies drugs and poisons.$ex16$,
    'easy', '2A', $cc16$Cell and Tissue Structure (BIO)$cc16$, 'biology', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'adjacent_fact', $a16A$Naming the same organelle's other sub-domain (RER) which does protein folding/modification rather than detoxification$a16A$ FROM q
UNION ALL SELECT id, 'B', 'misconception', $a16B$Conflating drug detoxification with lysosomal acid-hydrolase degradation of macromolecules$a16B$ FROM q
UNION ALL SELECT id, 'D', 'process_step_confusion', $a16D$Substituting the protein-synthesis machinery (ribosomes) for the detoxification organelle$a16D$ FROM q;

-- Q8 [Endoplasmic Reticulum · medium · Skill 2 · ans D] (g17)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'bio_biochem', 'The Cell', 'Endoplasmic Reticulum',
    $qt17$An adrenal cortex cell is specialized to synthesize and secrete large quantities of cortisol, a steroid hormone derived from cholesterol. Which feature would an electron micrograph of this cell most likely reveal as unusually abundant?$qt17$,
    $op17$[{"label":"A","text":"Rough endoplasmic reticulum, because a cell that secretes a hormone must synthesize that hormone on membrane-bound ribosomes"},{"label":"B","text":"Rough endoplasmic reticulum, because lipid-derived molecules such as cholesterol are assembled in the RER lumen before secretion"},{"label":"C","text":"Golgi apparatus, because the cortisol must be sorted and tagged with sugar chains before it exits the cell"},{"label":"D","text":"Smooth endoplasmic reticulum, because steroid hormones are lipid-derived and the SER is the site of lipid and steroid-hormone synthesis"}]$op17$::jsonb,
    'D',
    $ex17$This is a Biology question that falls under the content category 'Cell and Tissue Structure (BIO)'. The answer is D because cortisol is a steroid (lipid-derived) hormone, and the smooth endoplasmic reticulum is the organelle that synthesizes lipids and steroid hormones. A cell's organelle profile reflects its function: a heavy steroid-synthesizing workload demands abundant SER, where lipid and steroid-hormone synthesis occurs, rather than the protein-handling machinery of the rough ER. The textbook states that smooth ER \"functions include synthesis of carbohydrates, lipids, and steroid hormones,\" whereas the rough ER serves cells that \"secrete proteins\" (line 5708). Because cortisol is built from cholesterol rather than from a polypeptide chain, ribosome-studded RER would not be the predominant feature; the lipid-synthesizing SER would be. (Choice A) This invokes the partial-truth that \"a cell that secretes, secretes via the RER\": the RER is indeed abundant in protein-secreting cells, but cortisol is a steroid, not a protein, so it is not assembled on ribosomes — RER abundance tracks protein secretion, not steroid secretion. (Choice B) This is a reversed relationship that assigns lipid/cholesterol assembly to the RER; the textbook places synthesis of lipids and steroid hormones in the SER (line 5713), while the RER's lumen handles protein folding and modification, so cholesterol-derived molecules are not built in the RER lumen. (Choice C) This is a process-step confusion: the Golgi sorts, tags, and adds sugar chains to proteins and lipids passing through it, but it is not the synthetic site for a steroid hormone, so its abundance would not be the defining feature of a steroid-producing cell. (Choice D) Correct: cortisol is lipid-derived, and the SER is the site of lipid and steroid-hormone synthesis (line 5713), so a cell devoted to cortisol production would be packed with smooth ER. This is a Scientific Reasoning and Problem Solving question because you must reason from the chemical nature of the secreted product (a lipid-derived steroid) to predict which organelle is enriched, rather than recall a single stated fact.$ex17$,
    'medium', '2A', $cc17$Cell and Tissue Structure (BIO)$cc17$, 'biology', 2, 100
  ) RETURNING id
)
